UPDATE tools SET faq = $x$[{"q": "В чём разница между FlutterFlow и Bubble?", "a": "FlutterFlow создаёт нативные мобильные приложения (iOS и Android) с использованием Flutter — он выводит настоящий код Flutter. Bubble создаёт веб-приложения со сложной логикой и базами данных, доступные через браузер. FlutterFlow предназначен для мобильных приложений; Bubble — для веб-приложений."}, {"q": "Может ли FlutterFlow экспортировать код?", "a": "Да. FlutterFlow может экспортировать готовый к продакшену код Flutter/Dart в GitHub или скачать его локально. Это означает, что вы можете начать визуально, а затем продолжить разработку в коде — вы не привязаны к платформе. Экспорт кода требует тарифа Basic ($39/месяц) или выше."}, {"q": "Сколько стоит FlutterFlow?", "a": "У FlutterFlow есть бесплатный тариф, ограниченный 2 проектами и 10 Lite-кредитами в месяц, без экспорта кода. Basic стоит $39/месяц и добавляет экспорт кода и APK. Growth стоит $80/месяц за первое место ($55/месяц за второе место) и добавляет интеграцию с GitHub. Business стоит $150/месяц за первое место (места 2-5 по $85/месяц каждое) и поддерживает до 5 пользователей. Также доступна скидка при годовой оплате."}]$x$::jsonb
 WHERE slug = 'flutterflow' AND lang = 'ru';

