UPDATE tools SET faq = $x$[{"q": "Quelle est la différence entre FlutterFlow et Bubble ?", "a": "FlutterFlow crée des applications mobiles natives (iOS et Android) avec Flutter — il produit du vrai code Flutter. Bubble crée des applications web avec une logique et des bases de données complexes, accessibles via un navigateur. FlutterFlow est destiné au mobile ; Bubble est destiné aux applications web."}, {"q": "FlutterFlow permet-il d'exporter du code ?", "a": "Oui. FlutterFlow peut exporter du code Flutter/Dart prêt pour la production vers GitHub ou le télécharger localement. Cela signifie que vous pouvez commencer visuellement et poursuivre le développement dans le code — vous n'êtes pas enfermé dans la plateforme. L'export de code nécessite le plan Basic (39 $/mois) ou supérieur."}, {"q": "Combien coûte FlutterFlow ?", "a": "FlutterFlow propose un plan Free limité à 2 projets et 10 crédits Lite par mois, sans export de code. Basic est à 39 $/mois et ajoute l'export de code et d'APK. Growth est à 80 $/mois pour le premier siège (55 $/mois pour un second siège) et ajoute l'intégration GitHub. Business est à 150 $/mois pour le premier siège (sièges 2 à 5 à 85 $/mois chacun) et prend en charge jusqu'à 5 utilisateurs. Une remise sur la facturation annuelle est également disponible."}]$x$::jsonb
