UPDATE tools SET faq = $x$[{"q": "Что такое Murf AI?", "a": "Murf — это платформа ИИ-озвучки. Её продукт Studio предлагает более 200 голосов на более чем 30 языках и акцентах для электронных курсов, обучающих видео, презентаций и маркетингового контента, со встроенным редактором для синхронизации озвучки с видео и слайдами. Murf также предлагает отдельный продукт для голосовых агентов диалога и API TTS с низкой задержкой."}, {"q": "Сколько стоит Murf AI?", "a": "Studio предлагает бесплатный тариф (10 минут/месяц, без скачивания, без коммерческих прав), тариф Creator по цене $19/месяц при годовой оплате ($228/год), тариф Business по цене $66/месяц при годовой оплате ($792/год) и индивидуальную цену для Enterprise. Murf API оплачивается по факту использования — за символ или минуту, с бесплатным ежемесячным кредитом для пробного использования."}, {"q": "Чем Murf AI отличается от ElevenLabs?", "a": "Продукт Studio компании Murf ориентирован на профессиональное производство озвучки с полноценным редактором — редактирование сценария, синхронизация со слайдами и музыка. Murf также теперь предлагает собственный продукт для голосовых агентов диалога и API TTS с низкой задержкой (Falcon), что ставит компанию в более прямую конкуренцию с предложениями ElevenLabs в области голосовых агентов и API, в дополнение к традиционному сценарию использования Studio для озвучки."}, {"q": "Поддерживает ли Murf AI клонирование голоса?", "a": "Клонирование голоса на заказ предлагается как дополнительная опция на тарифе Studio Enterprise, а профессиональное клонирование голоса также указано в тарифе Enterprise для API. Оно не включено в тариф Business."}]$x$::jsonb
