UPDATE tools SET faq = $x$[{"q": "Що таке Murf AI?", "a": "Murf — це платформа голосового ШІ. Її продукт Studio пропонує 200+ голосів у 30+ мовах і акцентах для електронного навчання, пояснювальних відео, презентацій і маркетингового контенту, з вбудованим редактором для синхронізації озвучки з відео та слайдами. Murf також пропонує окремий продукт для розмовних голосових агентів і низьколатентний API для TTS."}, {"q": "Скільки коштує Murf AI?", "a": "Studio має безплатний план (10 хвилин/місяць, без завантажень, без комерційних прав), план Creator за 19 $/місяць з річним виставленням рахунку (228 $/рік), план Business за 66 $/місяць з річним виставленням рахунку (792 $/рік) та індивідуальне ціноутворення Enterprise. Murf API оплачується за фактичним використанням за символами або хвилинами, з безплатним щомісячним кредитом для пробного використання."}, {"q": "Чим Murf AI відрізняється від ElevenLabs?", "a": "Продукт Murf Studio зосереджений на професійному виробництві озвучки з повноцінним редактором — редагування сценарію, синхронізація зі слайдами та музика. Murf також тепер пропонує власний продукт розмовних голосових агентів і низьколатентний API для TTS (Falcon), що ставить компанію в пряму конкуренцію з пропозиціями голосових агентів та API ElevenLabs, на додаток до традиційного застосування Studio для озвучки."}, {"q": "Чи підтримує Murf AI клонування голосу?", "a": "Клонування голосу на замовлення пропонується як додаткова опція в плані Studio Enterprise, а професійне клонування голосу також вказано в тарифі API Enterprise. Воно не включене в план Business."}]$x$::jsonb
