UPDATE tools SET faq = $x$[{"q": "O que é a Murf AI?", "a": "Murf é uma plataforma de voz com IA. Seu produto Studio oferece mais de 200 vozes em mais de 30 idiomas e sotaques para e-learning, vídeos explicativos, apresentações e conteúdo de marketing, com um editor integrado para sincronizar a locução com vídeo e slides. A Murf também oferece um produto separado de agentes de voz conversacionais e uma API de TTS de baixa latência."}, {"q": "Quanto custa a Murf AI?", "a": "O Studio tem um plano Free (10 minutos/mês, sem downloads, sem direitos comerciais), um plano Creator listado a US$ 19/mês cobrado anualmente (US$ 228/ano), um plano Business listado a US$ 66/mês cobrado anualmente (US$ 792/ano), e preço Enterprise personalizado. A Murf API é cobrada por uso, por caractere ou minuto, com um crédito mensal gratuito para uso de teste."}, {"q": "Qual a diferença entre a Murf AI e a ElevenLabs?", "a": "O produto Studio da Murf foca na produção profissional de locução com um editor completo — edição de roteiro, sincronização com slides e música. A Murf também oferece agora seu próprio produto de agentes de voz conversacionais e uma API de TTS de baixa latência (Falcon), o que a coloca em concorrência mais direta com as ofertas de agentes de voz e API da ElevenLabs, além do caso de uso tradicional de locução do Studio."}, {"q": "A Murf AI suporta clonagem de voz?", "a": "A clonagem de voz personalizada é oferecida como complemento no plano Studio Enterprise, e a clonagem de voz profissional também está listada no nível Enterprise da API. Não está incluída no plano Business."}]$x$::jsonb
 WHERE slug = 'murf-ai' AND lang = 'pt';

