 WHERE slug = 'replit' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Replit?", "a": "Replit is a browser-based IDE and cloud development platform. You write, run, and deploy code entirely in the browser — no local installation needed. It supports many programming languages and Replit Agent provides AI coding assistance."}, {"q": "Is Replit free?", "a": "Replit's pricing page does not currently list a free account tier. Free Mode is a usage mode inside the paid Core and Pro plans, with limited hours and project counts that reset every 5 hours. Core starts at $20/month billed monthly, or $18/month billed annually."}, {"q": "Can Replit deploy web apps?", "a": "Yes. Replit has built-in deployments — you can deploy web apps, APIs, and databases directly from your Replit environment. Apps run on Replit's infrastructure at a .replit.app subdomain or custom domain."}, {"q": "Is Replit good for beginners?", "a": "Yes. Replit is one of the more accessible platforms for beginners — no setup required, works in any browser, and supports many programming languages. The AI agent helps explain code and fix errors. Many coding bootcamps and schools use Replit for this reason."}]$x$::jsonb
 WHERE slug = 'replit' AND lang = 'en';

