UPDATE tools SET faq = $x$[{"q": "Was ist Replit?", "a": "Replit ist eine browserbasierte IDE und Cloud-Entwicklungsplattform. Sie schreiben, führen aus und deployen Code vollständig im Browser — ohne lokale Installation. Sie unterstützt viele Programmiersprachen, und Replit Agent bietet KI-gestützte Coding-Unterstützung."}, {"q": "Ist Replit kostenlos?", "a": "Die Preisseite von Replit listet derzeit keine kostenlose Kontostufe. Free Mode ist ein Nutzungsmodus innerhalb der kostenpflichtigen Core- und Pro-Pläne mit begrenzten Stunden und Projektanzahlen, die sich alle 5 Stunden zurücksetzen. Core startet bei 20 $/Monat bei monatlicher Abrechnung oder 18 $/Monat bei jährlicher Abrechnung."}, {"q": "Kann Replit Web-Apps deployen?", "a": "Ja. Replit verfügt über integrierte Deployments — Sie können Web-Apps, APIs und Datenbanken direkt aus Ihrer Replit-Umgebung heraus deployen. Apps laufen auf der Infrastruktur von Replit unter einer .replit.app-Subdomain oder einer eigenen Domain."}, {"q": "Ist Replit gut für Anfänger geeignet?", "a": "Ja. Replit ist eine der zugänglicheren Plattformen für Anfänger — keine Einrichtung erforderlich, funktioniert in jedem Browser und unterstützt viele Programmiersprachen. Der KI-Agent hilft dabei, Code zu erklären und Fehler zu beheben. Viele Coding-Bootcamps und Schulen nutzen Replit aus diesem Grund."}]$x$::jsonb
 WHERE slug = 'replit' AND lang = 'de';

