UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Replit ?", "a": "Replit est un IDE basé sur le navigateur et une plateforme de développement cloud. Vous écrivez, exécutez et déployez du code entièrement dans le navigateur — aucune installation locale n'est nécessaire. Il prend en charge de nombreux langages de programmation et Replit Agent fournit une assistance de codage par IA."}, {"q": "Replit est-il gratuit ?", "a": "La page de tarification de Replit ne mentionne actuellement aucun palier de compte gratuit. Free Mode est un mode d'utilisation au sein des plans payants Core et Pro, avec des heures et un nombre de projets limités qui se réinitialisent toutes les 5 heures. Core démarre à 20 $/mois facturés mensuellement, ou 18 $/mois facturés annuellement."}, {"q": "Replit peut-il déployer des applications web ?", "a": "Oui. Replit dispose de déploiements intégrés — vous pouvez déployer des applications web, des API et des bases de données directement depuis votre environnement Replit. Les applications s'exécutent sur l'infrastructure de Replit à l'adresse d'un sous-domaine .replit.app ou d'un domaine personnalisé."}, {"q": "Replit est-il adapté aux débutants ?", "a": "Oui. Replit est l'une des plateformes les plus accessibles pour les débutants — aucune configuration requise, fonctionne dans n'importe quel navigateur, et prend en charge de nombreux langages de programmation. L'agent IA aide à expliquer le code et à corriger les erreurs. De nombreux bootcamps de codage et écoles utilisent Replit pour cette raison."}]$x$::jsonb
