UPDATE tools SET faq = $x$[{"q": "Was ist Synthesis?", "a": "Synthesis ist ein KI-gestütztes Bildungsunternehmen mit zwei Produkten: Synthesis Tutor, ein adaptives Mathematikprogramm für Kinder von 5 bis 11 Jahren, und Synthesis Teams, ein spielbasiertes Programm für Problemlösung und kritisches Denken für Kinder von 8 bis 14 Jahren. Das Unternehmen entstand 2014, als Elon Musk den Gründer Josh Dahn bat, eine experimentelle Schule für die Kinder von SpaceX-Mitarbeitern zu gründen, bevor die Programme öffentlich zugänglich gemacht wurden."}, {"q": "Ist Synthesis kostenlos?", "a": "Synthesis bietet keinen kostenlosen Plan an. Es gibt eine 7-tägige kostenlose Testphase für die Individual- und Family-Abonnementpläne, jedoch nicht für Lifetime-Käufe. Individual-Pläne und Family-Pläne (die bis zu 7 Kinder abdecken) sind mit monatlicher, jährlicher oder einmaliger Lifetime-Abrechnung verfügbar, wobei sich die Aktionspreise auf der Website des Anbieters regelmäßig ändern. Es ist als premium Bildungsergänzung positioniert, nicht als Ersatz für die Schule."}, {"q": "Was ist der Unterschied zwischen Synthesis und Khan Academy?", "a": "Khan Academy ist eine breit angelegte, kostenlose Bildungsplattform, die alle Fächer mit Videolektionen und Übungsaufgaben abdeckt. Synthesis konzentriert sich speziell auf Mathematik und Problemlösung durch Spiele und verwendet einen anderen pädagogischen Ansatz. Synthesis ist kostenpflichtig; Khan Academy ist kostenlos. Khanmigo ergänzt Khan Academy um KI-gestütztes Tutoring."}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'de';

