UPDATE tools SET faq = $x$[{"q": "Що таке Synthesis?", "a": "Synthesis — це освітня компанія з підтримкою штучного інтелекту, яка пропонує два продукти: Synthesis Tutor — адаптивну програму з математики для дітей 5-11 років, та Synthesis Teams — ігрову програму для розвитку навичок розв'язання задач і критичного мислення для дітей 8-14 років. Компанія виникла у 2014 році, коли засновник Josh Dahn отримав від Elon Musk пропозицію запустити експериментальну школу для дітей співробітників SpaceX, перш ніж відкрити свої програми для широкого загалу."}, {"q": "Чи безкоштовний Synthesis?", "a": "Synthesis не має безкоштовного плану. Компанія пропонує 7-денну безкоштовну пробну версію для тарифів Individual та Family, але не для довічних покупок. Тарифи Individual та Family (що охоплюють до 7 дітей) доступні з щомісячною, щорічною або одноразовою довічною оплатою, а акційні ціни на сайті постачальника періодично змінюються. Позиціонується як преміальне освітнє доповнення, а не заміна школи."}, {"q": "У чому різниця між Synthesis та Khan Academy?", "a": "Khan Academy — це широка безкоштовна освітня платформа, що охоплює всі предмети за допомогою відеоуроків і практичних завдань. Synthesis зосереджується конкретно на математиці та розв'язанні задач через ігри, використовуючи інший педагогічний підхід. Synthesis — платний сервіс; Khan Academy — безкоштовний. Khanmigo додає ШІ-репетиторство до Khan Academy."}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'ua';

