UPDATE tools SET faq = $x$[{"q": "מהי Synthesis?", "a": "Synthesis היא חברת למידה מבוססת בינה מלאכותית עם שני מוצרים: Synthesis Tutor, תוכנית חשבון אדפטיבית לגילאי 5-11, ו-Synthesis Teams, תוכנית מבוססת-משחק לפתרון בעיות וחשיבה ביקורתית לגילאי 8-14. החברה החלה את דרכה בשנת 2014, כאשר המייסד Josh Dahn התבקש על ידי Elon Musk להקים בית ספר ניסיוני לילדיהם של עובדי SpaceX, לפני שפתחה את התוכניות שלה לציבור הרחב."}, {"q": "האם Synthesis חינמית?", "a": "ל-Synthesis אין תוכנית חינמית. היא מציעה תקופת ניסיון חינם בת 7 ימים בתוכניות המנוי Individual ו-Family, אך לא ברכישות Lifetime. תוכניות Individual ותוכניות Family (המכסות עד 7 ילדים) זמינות בחיוב חודשי, שנתי, או רכישה חד-פעמית לכל החיים, כאשר מחירי המבצע משתנים מעת לעת באתר הספק. היא ממוקמת כתוסף חינוכי פרימיום ולא כתחליף לבית הספר."}, {"q": "מה ההבדל בין Synthesis ל-Khan Academy?", "a": "Khan Academy היא פלטפורמת חינוך רחבה וחינמית המכסה את כל המקצועות באמצעות שיעורי וידאו ותרגילים. Synthesis מתמקדת ספציפית בחשבון ובפתרון בעיות באמצעות משחקים, תוך שימוש בגישה פדגוגית שונה. Synthesis היא פרימיום; Khan Academy חינמית. Khanmigo מוסיף הדרכה מבוססת בינה מלאכותית ל-Khan Academy."}]$x$::jsonb
