UPDATE tools SET faq = $x$[{"q": "O que é Synthesis?", "a": "Synthesis é uma empresa de aprendizado com tecnologia de IA que oferece dois produtos: Synthesis Tutor, um programa adaptativo de matemática para idades de 5 a 11 anos, e Synthesis Teams, um programa baseado em jogos de resolução de problemas e pensamento crítico para idades de 8 a 14 anos. A empresa surgiu em 2014, quando o fundador Josh Dahn foi convidado por Elon Musk para lançar uma escola experimental para os filhos de funcionários da SpaceX, antes de abrir seus programas ao público."}, {"q": "O Synthesis é gratuito?", "a": "O Synthesis não possui plano gratuito. Ele oferece um teste gratuito de 7 dias nos planos de assinatura Individual e Family, mas não nas compras Lifetime. Os planos Individual e Family (cobrindo até 7 crianças) estão disponíveis com cobrança mensal, anual ou única vitalícia, com preços promocionais que mudam periodicamente no site do fornecedor. É posicionado como um complemento educacional premium, e não como substituto da escola."}, {"q": "Qual é a diferença entre Synthesis e Khan Academy?", "a": "Khan Academy é uma plataforma educacional ampla e gratuita que cobre todas as disciplinas com videoaulas e exercícios práticos. O Synthesis foca especificamente em matemática e resolução de problemas por meio de jogos, usando uma abordagem pedagógica diferente. O Synthesis é premium; a Khan Academy é gratuita. O Khanmigo adiciona tutoria com IA à Khan Academy."}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'pt';

