UPDATE tools SET faq = $x$[{"q": "Что такое Uizard?", "a": "Uizard — это инструмент дизайна UI на базе AI, который превращает эскизы, скриншоты или текстовые описания в цифровые вайрфреймы и макеты. Он создан для людей без дизайнерских навыков — продакт-менеджеров, основателей и предпринимателей, которым нужно быстро визуализировать идеи приложений, не изучая Figma."}, {"q": "Uizard бесплатный?", "a": "У Uizard есть бесплатный план с 2 проектами, 10 шаблонами и 3 AI-генерациями в месяц. Pro стоит $12 в месяц при годовой оплате, а Business — $39 в месяц при годовой оплате, за них даётся больше проектов, кредитов AI-генерации и командных функций."}, {"q": "Может ли Uizard экспортировать в Figma?", "a": "Uizard может экспортировать дизайны, которые можно открыть в Figma. Этот рабочий процесс — создание вайрфреймов в Uizard, доработка в Figma — используется командами, которые начинают с грубых концепций и переходят к профессиональному дизайну."}]$x$::jsonb
