UPDATE tools SET faq = $x$[{"q": "Qu'est-ce qu'Uizard ?", "a": "Uizard est un outil de conception d'UI alimenté par l'IA qui transforme des croquis, des captures d'écran ou des descriptions textuelles en wireframes et maquettes numériques. Il est conçu pour les non-designers — chefs de produit, fondateurs et entrepreneurs qui ont besoin de visualiser rapidement des idées d'applications sans apprendre Figma."}, {"q": "Uizard est-il gratuit ?", "a": "Uizard propose un plan gratuit avec 2 projets, 10 modèles et 3 générations IA par mois. Pro coûte 12 $ par mois facturé annuellement, et Business coûte 39 $ par mois facturé annuellement, pour plus de projets, de crédits de génération IA et de fonctionnalités d'équipe."}, {"q": "Uizard peut-il exporter vers Figma ?", "a": "Uizard peut exporter des designs qui peuvent être ouverts dans Figma. Ce flux de travail — générer des wireframes dans Uizard, puis les affiner dans Figma — est utilisé par les équipes qui partent de concepts approximatifs pour aller vers un design professionnel."}]$x$::jsonb
